using System.Reflection;
using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    // Technical details the inner layers must not touch directly.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.Net", "System.IO", "System.Text.Json", "System.Data", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    private static Assembly Load(string name) => Assembly.Load(name);

    private static void AssertNoDependencies(string layer, string[] forbidden)
    {
        var result = Types.InAssembly(Load(layer)).That().ResideInNamespaceStartingWith(layer)
            .ShouldNot().HaveDependencyOnAny(forbidden).GetResult();

        Assert.True(result.IsSuccessful,
            $"{layer} must not depend on {string.Join(", ", forbidden)}. Offenders: {string.Join(", ", result.FailingTypeNames ?? [])}");
    }

    [Fact]
    public void Domain_depends_on_no_other_layer_and_no_technical_detail() =>
        AssertNoDependencies(Domain, [Application, Infrastructure, .. TechnicalNamespaces]);

    [Fact]
    public void Application_depends_on_neither_infrastructure_nor_technical_detail() =>
        AssertNoDependencies(Application, [Infrastructure, .. TechnicalNamespaces]);
}
